// backend/test/fixtures/stored-file-samples.ts
//
// 合成夹具（不含真实用户原件）：
// - Office 样本由 LibreOffice 24.2.7.2 从无敏感信息的示例 HTML/CSV/ODP 转换生成：
//   sample.html -> sample.docx / sample.doc；sample.csv -> sample.xlsx / sample.xls；
//   sample.odp -> sample.pptx / sample.ppt。
// - 样本以 gzip+base64 保存，测试时解压为真实有效的 Office 文件。
// - PNG/JPEG 为 2x2 纯白合成图片。

import { gunzipSync } from 'node:zlib';

const compressedOfficeSamples = {
  doc: '',
  docx: '',
  xls: '',
  xlsx: '',
  ppt: '',
  pptx: '',
} as const;

export type OfficeSampleExtension = keyof typeof compressedOfficeSamples;

export const officeSamples: Readonly<Record<OfficeSampleExtension, Buffer>> = {
  doc: gunzipSync(Buffer.from(compressedOfficeSamples.doc, 'base64')),
  docx: gunzipSync(Buffer.from(compressedOfficeSamples.docx, 'base64')),
  xls: gunzipSync(Buffer.from(compressedOfficeSamples.xls, 'base64')),
  xlsx: gunzipSync(Buffer.from(compressedOfficeSamples.xlsx, 'base64')),
  ppt: gunzipSync(Buffer.from(compressedOfficeSamples.ppt, 'base64')),
  pptx: gunzipSync(Buffer.from(compressedOfficeSamples.pptx, 'base64')),
};

export const minimalPng = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR4nGP8//8/AwMDEwMDAwMDAwAkBgMB/DXemwAAAABJRU5ErkJggg==',
  'base64',
);

export const minimalJpeg = Buffer.from(
  '',
  'base64',
);

const CFB_END_OF_CHAIN = 0xfffffffe;
const CFB_FREE_SECTOR = 0xffffffff;

export type CfbChainTailFixture = {
  buffer: Buffer;
  /** 链尾后继值所在字节偏移；正负样本只允许该处不同。 */
  terminatorOffset: number;
  /** 该链实际经过的扇区 ID；DIFAT 夹具借此证明至少遍历了一个 DIFAT 扇区。 */
  chainSectors: number[];
  /** 从头部 DIFAT 迁移到 DIFAT 扇区的 FAT 扇区 ID；目录链夹具为空。 */
  relocatedFatSectorIds: number[];
};

function cfbSectorSize(sample: Buffer): number {
  return 1 << sample.readUInt16LE(30);
}

function readHeaderFatSectorIds(sample: Buffer): Array<{ slot: number; sectorId: number }> {
  const entries: Array<{ slot: number; sectorId: number }> = [];
  for (let slot = 0; slot < 109; slot += 1) {
    const sectorId = sample.readUInt32LE(76 + slot * 4);
    if (sectorId !== CFB_FREE_SECTOR) {
      entries.push({ slot, sectorId });
    }
  }
  return entries;
}

/** 复制样本，仅把目录链最后一个扇区的后继值改写为 terminator。 */
export function buildCfbDirectoryChainTailFixture(
  sample: Buffer,
  terminator: number,
): CfbChainTailFixture {
  const sectorSize = cfbSectorSize(sample);
  const headerFatSectors = readHeaderFatSectorIds(sample);
  const fat: number[] = [];
  for (const { sectorId } of headerFatSectors) {
    const offset = (sectorId + 1) * sectorSize;
    for (let cursor = offset; cursor < offset + sectorSize; cursor += 4) {
      fat.push(sample.readUInt32LE(cursor));
    }
  }

  const chainSectors: number[] = [];
  let sector = sample.readUInt32LE(48);
  while (sector !== CFB_END_OF_CHAIN && sector !== CFB_FREE_SECTOR && chainSectors.length < 4096) {
    chainSectors.push(sector);
    sector = fat[sector];
  }
  if (chainSectors.length === 0) {
    throw new Error('cfb directory chain empty');
  }

  const lastSector = chainSectors[chainSectors.length - 1];
  const entriesPerSector = sectorSize / 4;
  const fatSectorId = headerFatSectors[Math.floor(lastSector / entriesPerSector)].sectorId;
  const terminatorOffset = (fatSectorId + 1) * sectorSize + (lastSector % entriesPerSector) * 4;

  const buffer = Buffer.from(sample);
  buffer.writeUInt32LE(terminator, terminatorOffset);
  return { buffer, terminatorOffset, chainSectors, relocatedFatSectorIds: [] };
}

/**
 * 在样本尾部追加一个 DIFAT 扇区，并把头部 DIFAT 的首个 FAT 扇区 ID 迁移进去。
 * 正例只能通过遍历 DIFAT 扇区收集到该 FAT 扇区 ID；负例仅把 DIFAT 链尾改为 terminator。
 */
export function buildCfbDifatChainTailFixture(
  sample: Buffer,
  terminator: number,
): CfbChainTailFixture {
  const sectorSize = cfbSectorSize(sample);
  if (sample.byteLength % sectorSize !== 0) {
    throw new Error('cfb sample not sector aligned');
  }
  const headerFatSectors = readHeaderFatSectorIds(sample);
  if (headerFatSectors.length === 0) {
    throw new Error('cfb sample has no header fat sector');
  }

  const migrated = headerFatSectors[0];
  const difatSectorId = sample.byteLength / sectorSize - 1;
  const difatSector = Buffer.alloc(sectorSize, 0xff);
  difatSector.writeUInt32LE(migrated.sectorId, 0);
  difatSector.writeUInt32LE(terminator, sectorSize - 4);

  const buffer = Buffer.concat([Buffer.from(sample), difatSector]);
  buffer.writeUInt32LE(CFB_FREE_SECTOR, 76 + migrated.slot * 4);
  buffer.writeUInt32LE(difatSectorId, 68);
  buffer.writeUInt32LE(1, 72);

  return {
    buffer,
    terminatorOffset: sample.byteLength + sectorSize - 4,
    chainSectors: [difatSectorId],
    relocatedFatSectorIds: [migrated.sectorId],
  };
}

/** 生成结构完整的最小 PDF；targetSize 用于验证 20,000,000 字节边界（尾部空白填充）。 */
export function makeMinimalPdf(targetSize = 0): Buffer {
  const header = '%PDF-1.4\n';
  const object = '1 0 obj\n<< /Type /Catalog >>\nendobj\n';
  const xrefOffset = header.length + object.length;
  const xref = `xref\n0 2\n0000000000 65535 f \n${String(header.length).padStart(10, '0')} 00000 n \n`;
  const trailer = `trailer\n<< /Size 2 /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;
  const pdf = Buffer.from(`${header}${object}${xref}${trailer}`, 'latin1');
  if (targetSize <= pdf.byteLength) {
    return pdf;
  }
  return Buffer.concat([pdf, Buffer.alloc(targetSize - pdf.byteLength, 0x20)]);
}
